// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *SalesShipmentLine) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, SalesShipmentLineTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, line_no)`,
		fmt.Sprintf("%s$Sales_Shipment_Line$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (type, no)`,
		fmt.Sprintf("%s$Sales_Shipment_Line$type_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_no: %w", err)
	}
	var keys []sift.Key
	for _, spec := range salesShipmentLineSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, SalesShipmentLineTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, SalesShipmentLineTableName, keys)
}

// salesShipmentLineSIFTSpecs are the table's keys with sum_index_fields
func salesShipmentLineSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *SalesShipmentLine) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, SalesShipmentLineTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range salesShipmentLineSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, SalesShipmentLineTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: SalesShipmentLineTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, SalesShipmentLineTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

